package com.university.modules.week09;
import javafx.application.Application;import javafx.concurrent.Task;import javafx.geometry.Insets;import javafx.scene.Scene;import javafx.scene.control.*;import javafx.scene.layout.VBox;import javafx.stage.Stage;
/** Week 9: Task-based background work, progress/message bindings, and completion handling. */
public class AsyncTaskDemo extends Application {
 @Override public void start(Stage stage){ProgressBar progress=new ProgressBar(0);progress.setMaxWidth(Double.MAX_VALUE);Label message=new Label("Idle");Button start=new Button("Run background task");start.setOnAction(e->{start.setDisable(true);Task<Void> task=new Task<>(){@Override protected Void call() throws Exception{for(int i=1;i<=10;i++){if(isCancelled())break;Thread.sleep(300);updateProgress(i,10);updateMessage("Working: "+(i*10)+"%");}return null;}};progress.progressProperty().bind(task.progressProperty());message.textProperty().bind(task.messageProperty());task.setOnSucceeded(x->{message.textProperty().unbind();message.setText("Task complete");start.setDisable(false);});task.setOnFailed(x->{message.textProperty().unbind();message.setText("Failed: "+task.getException().getMessage());start.setDisable(false);});Thread worker=new Thread(task,"week09-worker");worker.setDaemon(true);worker.start();});VBox box=new VBox(14,new Label("Background Task and progress binding"),progress,message,start);box.setPadding(new Insets(20));stage.setScene(new Scene(box,480,180));stage.setTitle("Week 9 — Async Task");stage.show();}
 public static void main(String[]a){launch(a);}
}
